A.Nw=new B.y(A.ao,"Kenali tiap cuaca",A.L,"Ayo kenali rupa tiap cuaca di langit!",null,"Tulis ciri tiap cuaca di sebelah gambarnya.",A.aDu,!0,null,null)
A.Mj=new B.y(A.ap,"Buat kalender cuaca!",A.L,"Sekarang kita jadi pengamat cuaca cilik!","Buat kalender cuaca seminggu. Tiap pagi ajak anak melihat langit dan menempel simbol cuaca hari itu. Akhir minggu, hitung bersama.",null,null,!1,null,null)
A.aMi=new B.aG("Langit gelap di siang hari berarti sudah malam.","Langit gelap di siang hari karena awan tebal banyak titik air, tanda mau hujan \u2014 bukan malam. Tunjuk jam untuk meyakinkan anak.")
A.aLU=new B.aG("Matahari hilang saat hujan karena pergi tidur.","Matahari tetap ada, hanya tertutup awan tebal. Setelah awan pergi, Matahari terlihat lagi.")
A.ajx=s([A.aMi,A.aLU],t.v)
A.Ot=new B.y(A.as,"Cek pemahaman",A.V,"Si Jabrik bingung \u2014 bantu dia! Kalau langit penuh awan gelap, cuaca apa yang mungkin datang? Dan apa yang sebaiknya kita bawa?","Minta anak menjawab dengan riang. Puji semua usaha.",null,null,!0,null,A.ajx)
A.LJ=new B.y(A.at,"WHAT?! \ud83e\udd2f",A.av,"Tahukah kalian? Awan yang terlihat empuk seperti kapas itu sebenarnya tersusun dari JUTAAN titik air yang sangat kecil dan ringan, melayang di udara. Saat titik-titik itu berkumpul jadi berat, turunlah hujan. Langit memang penuh keajaiban!","Tepuk tangan untuk langit dan awan-awannya!",null,null,!1,null,null)
