A.aVs=new B.Y("menguap","\ud83d\udca8","Menguap","MENGUAP: cair jadi gas karena panas. Contoh: air jemuran kering, air mendidih berubah jadi uap.")
A.aUA=new B.Y("mengembun","\ud83d\udca7","Mengembun","MENGEMBUN: gas jadi cair karena dingin. Contoh: titik air di gelas es, embun pagi di daun.")
A.aFe=s([A.aUi,A.aVp,A.aVs,A.aUA],t.l)
